TP.register({id:"lp4-g1",lp:4,grade:"1",mode:"baseline",nextGrade:"2nd grade",build(E){const F=E.F;const ICON=(name,size)=>(F.icon||F.pic2)(name,size);const STORY="Tess had a new sled. It was red. Snow fell all night. It covered the big hill. In the morning Tess went out. She took her sled up the hill. At the top she saw Nico. He was sitting in the snow. His sled was stuck. It was under a pine tree. He could not pull it out alone. Tess pulled the other end. Up came the sled! Then they slid down the hill together. Nico said it was the best ride. It was the best ride all winter.";const GROUNDHOG="Some animals sleep through the whole winter, and a groundhog is one of them. In the fall, a groundhog eats and eats. It eats a lot of food so that its body has plenty of fat. Then it digs a den under the ground. The den stays warm even when the air gets cold. The groundhog curls up in a ball and sleeps for months. It does not need to eat at all. In the spring it wakes up and comes out to look for fresh grass.";const POND="When the air gets very cold, the top of a pond turns to ice. The ice starts out thin. It gets thicker on each cold night. Fish still swim in the water under the ice. A village worker drills a small hole and drops in a stick to measure the ice. When the ice is thick enough, people skate on the pond.";const WORDS=["shed","chip","pine","home","coat","feet","packed","mitten","cabin","they","flane","chud"];const INK=window.TP_ICON_INK||"#6B4A3C";const kEye=(x,y,r)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="#4A332A"/><circle cx="${(x-r*.32).toFixed(1)}" cy="${(y-r*.39).toFixed(1)}" r="${(r*.36).toFixed(1)}" fill="#FFFFFF"/>`;const kBlush=(x,y,r)=>`<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${(r*1.48).toFixed(1)}" ry="${(r*.95).toFixed(1)}" fill="#F49AAB" opacity=".9"/>`;const kSmile=(x,y,w)=>`<path d="M${(x-w).toFixed(1)} ${y.toFixed(1)} q${w.toFixed(1)} ${w.toFixed(1)} ${(w*2).toFixed(1)} 0" fill="none" stroke="#4A332A" stroke-width="${Math.max(1.2,w*.65).toFixed(1)}" stroke-linecap="round"/>`;const kFace=(cx,cy,r)=>{const e=r*.26;return kEye(cx-r*.42,cy,e)+kEye(cx+r*.42,cy,e)+kBlush(cx-r*.84,cy+r*.5,e)+kBlush(cx+r*.84,cy+r*.5,e)+kSmile(cx,cy+r*.5,r*.24)};const WOOD="#E6C79B",PAPER="#FFFDF7",SHADE="#F6D45E",CUBE="#DCEEFB";function sledShape(x,y,s){const sw=Math.max(2,s*.06).toFixed(1),x0=x-s/2,y0=y-s*.19,seatH=s*.28;return`<rect x="${(x0+s*.06).toFixed(1)}" y="${y0.toFixed(1)}" width="${(s*.8).toFixed(1)}" height="${seatH.toFixed(1)}" rx="${(seatH*.4).toFixed(1)}" fill="${WOOD}" stroke="${INK}" stroke-width="${sw}"/><path d="M${(x0+s*.22).toFixed(1)} ${(y0+seatH).toFixed(1)} v${(s*.38-seatH).toFixed(1)} M${(x0+s*.7).toFixed(1)} ${(y0+seatH).toFixed(1)} v${(s*.38-seatH).toFixed(1)}" stroke="${INK}" stroke-width="${(s*.075).toFixed(1)}" stroke-linecap="round"/><path d="M${(x0+s*.02).toFixed(1)} ${(y0+s*.38).toFixed(1)} H${(x0+s*.8).toFixed(1)} q${(s*.16).toFixed(1)} 0 ${(s*.18).toFixed(1)} ${(-s*.14).toFixed(1)}" fill="none" stroke="#8FA2AE" stroke-width="${(s*.07).toFixed(1)}" stroke-linecap="round"/>`+kFace(x0+s*.46,y0+seatH*.38,seatH*.64)}function sledCard(cap){return[`<svg viewBox="0 0 90 90" width="90" role="img" aria-label="${cap}">${sledShape(45,48,80)}</svg>`,cap]}function pic(e,cap){return[`<svg viewBox="0 0 90 90" width="90" role="img" aria-label="${cap}">${F.picXY(45,48,e,54)||`<text x="45" y="48" font-size="54" text-anchor="middle" dominant-baseline="central">${e}</text>`}</svg>`,cap]}function cube(x,y,w,fill){return`<rect x="${x}" y="${y}" width="${w}" height="${w}" fill="${fill||CUBE}" stroke="${INK}" stroke-width="2.5"/>`}function measureFig(){let a=`<svg viewBox="0 0 300 108" width="300" role="img" aria-label="A sled with six cubes in a row under it, end to end">`;a+=`<rect x="20" y="10" width="240" height="26" rx="13" fill="${WOOD}" stroke="${INK}" stroke-width="2.5"/>`;a+=`<path d="M20 40 h240" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>`;for(let i=0;i<6;i++)a+=cube(20+i*40,56,40);a+="</svg>";let b=`<svg viewBox="0 0 300 108" width="300" role="img" aria-label="A ski with five cubes under it, some big and some small">`;b+=`<rect x="20" y="12" width="168" height="22" rx="11" fill="#9AD2EC" stroke="${INK}" stroke-width="2.5"/>`;b+=`<path d="M20 40 h168" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>`;let bx=20;[40,24,40,24,40].forEach(w=>{b+=cube(bx,96-w,w,w===40?CUBE:SHADE);bx+=w});b+="</svg>";return F.row([a,"Sled"],[b,"Ski"])}function rectFourths(){let s=`<svg viewBox="0 0 196 60" width="196" role="img" aria-label="Rectangle cut into four equal parts"><rect x="4" y="4" width="188" height="52" fill="${PAPER}" stroke="${INK}" stroke-width="3"/>`;[51,98,145].forEach(x=>{s+=`<line x1="${x}" y1="4" x2="${x}" y2="56" stroke="${INK}" stroke-width="3"/>`});return s+"</svg>"}function rectUneven(){let s=`<svg viewBox="0 0 196 60" width="196" role="img" aria-label="Rectangle cut into four parts that are not the same size"><rect x="4" y="4" width="188" height="52" fill="${PAPER}" stroke="${INK}" stroke-width="3"/>`;[24,56,158].forEach(x=>{s+=`<line x1="${x}" y1="4" x2="${x}" y2="56" stroke="${INK}" stroke-width="3"/>`});return s+"</svg>"}function circleFourths(){return`<svg viewBox="0 0 160 160" width="160" role="img" aria-label="Circle cut into four equal parts by two slanted lines, one part shaded"><circle cx="80" cy="80" r="70" fill="${PAPER}" stroke="${INK}" stroke-width="3"/><path d="M80 80 L129.5 30.5 A70 70 0 0 1 129.5 129.5 Z" fill="${SHADE}" stroke="${INK}" stroke-width="3"/><line x1="30.5" y1="30.5" x2="129.5" y2="129.5" stroke="${INK}" stroke-width="3"/><line x1="129.5" y1="30.5" x2="30.5" y2="129.5" stroke="${INK}" stroke-width="3"/></svg>`}function sharesFig(){return F.row([circleFourths(),"Circle"],[rectFourths(),"Rectangle A"],[rectUneven(),"Rectangle B"])}function graphHtml(){const data=[["Sled",8],["Skates",5],["Snowshoes",E.state.shoe||0]],cell=32,x0=76,y0=34,rows=10,bw=98;let s=`<svg viewBox="0 0 ${x0+data.length*bw+24} ${y0+rows*cell+66}" width="${x0+data.length*bw+24}" role="img" aria-label="Bar graph of winter fun picks">`;s+=`<text x="${(x0+data.length*bw)/2+12}" y="20" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" font-size="21" fill="var(--ink)">Winter Fun Picks</text>`;for(let r=0;r<=rows;r++){const y=y0+8+(rows-r)*cell;s+=`<line x1="${x0}" y1="${y}" x2="${x0+data.length*bw}" y2="${y}" stroke="var(--line)" stroke-width="2"/><text x="${x0-12}" y="${y}" text-anchor="end" dominant-baseline="central" font-size="17" fill="var(--ink)">${r}</text>`}data.forEach((d,i)=>{const bx=x0+i*bw+18;for(let r=0;r<rows;r++){const y=y0+8+(rows-r-1)*cell,filled=r<d[1];if(i===2)s+=`<rect class="oc" data-r="${r+1}" x="${bx}" y="${y}" width="62" height="${cell}" fill="${filled?"var(--gold)":"transparent"}" stroke="var(--sea)" stroke-dasharray="${filled?"0":"4 4"}" stroke-width="2" style="cursor:pointer"/>`;else if(filled)s+=`<rect x="${bx}" y="${y}" width="62" height="${cell}" fill="var(--sea)" stroke="var(--surface)" stroke-width="2"/>`}s+=`<text x="${bx+31}" y="${y0+8+rows*cell+28}" text-anchor="middle" font-size="17" font-weight="700" fill="var(--ink)">${d[0]}</text>`});return s+"</svg>"}const STOPS=[{id:1,title:"Snow Sounds",short:"Snow Sounds",parts:[{std:["RF.1.2"],n:6,dur:75,html:()=>`<p class="huge" aria-hidden="true">${ICON("ear",96)}</p>`,key:["Blend: /s/ /l/ /e/ /d/ (sled)","Blend: /m/ /e/ /l/ /t/ (melt)","What is the middle sound in hot? (/o/)","What are the first and last sounds in chill? (/ch/ and /l/)","Say all the sounds in skate. (/s/ /k/ /a/ /t/, four sounds)","Long or short vowel: rope? nest? (rope long, nest short; both needed)"]}]},{id:2,title:"Mitten Words",short:"Mitten Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:105,key:["Read each word out loud. flane and chud are silly words: listen for the silent e in flane and the ch in chud.","Watch for: digraphs (shed, chip), final e (pine, home), vowel teams (coat, feet), the -ed ending (packed), two syllables (mitten, cabin), and the tricky word (they).","Optional: ask how many syllables are in cabin (2). Add to notes."]}]},{id:3,title:"Sled Hill Story",short:"Sled Story",parts:[{std:["RF.1.4"],kind:"fable",n:75,label:"words read correctly",dur:120,html:()=>`${F.row(sledCard("a sled"),pic("pine","a pine tree"),pic("snowflake","snow"))}<p class="passage">${STORY}</p>`,key:["75 words. Mark errors and self-corrections on the large-print passage in the record sheet.","Point to the three pictures first so the words sled, pine tree, and snow are clear before the student reads.","Note pace, expression, and whether the student rereads to fix mistakes."]}]},{id:4,title:"Top of the Hill",short:"Sled Hill",parts:[{title:"Print Detective",std:["RF.1.1"],dur:40,html:()=>`<p class="passage" style="font-size:1.4rem">${STORY}</p>`,qs:["Find the sentence that begins with the word Snow. What do you notice about the first letter of that word? Does every sentence in this story start that way?","One sentence ends with a mark that is not a period. Find it and read that sentence. What is the mark called?","I will point to a period in the story. Show me the first word of the very next sentence and read it to me. How do you know a new sentence starts there?"],key:["Shows the capital S in Snow and says a sentence begins with a capital letter. Yes, every sentence in the story starts with a capital letter (RF.1.1)","Reads the short sentence about the sled coming up and names the mark, exclamation mark or exclamation point (RF.1.1)","Point to the period after the big hill. Student points to the word In, reads it, and says the new sentence starts there because that word comes after the end mark and begins with a capital letter (RF.1.1)"]},{title:"Story Questions",std:["RL.1.1"],dur:90,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>`<p class="passage">${STORY}</p>`,qs:["Where was Nico’s sled stuck?","What did Tess do when she saw Nico?","What did the two of them do once the sled was out?","Ask me a question about the story."],key:["Under a pine tree. Just “under a pine tree” is correct; adding that it was at the top of the hill is also correct (RL.1.1)","She pulled the other end of his sled until it came free (RL.1.1)","Rode down the hill together (RL.1.1)","Asks a real question about the story (RL.1.1)"]},{wt:"opinion",gxHome:13,title:"Opinion Writing",std:["W.1.1","W.1.8","L.1.1"],n:7,label:"checks met",dur:180,html:()=>`<p class="big">Was Tess a good friend to Nico? Write what you think and tell why. Use the story.</p><ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul><details class="look-back" open><summary>Look back at the story</summary><p class="passage" style="font-size:1.5rem">${STORY}</p></details>`,key:["Names the story or the people in it (W.1.1)","States an opinion about Tess (W.1.1)","Gives a reason for the opinion (W.1.1)","Uses a detail from the story as the reason (W.1.8)","Gives some sense of closure (W.1.1)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]}]},{id:5,title:"Fix the Frost",short:"Fix It",parts:[{std:["L.1.1"],dur:60,qs:["Today I skate. Yesterday I ____.","Today I shovel. Tomorrow I ____ shovel.","She slides. They ____.","Pick the right word: Ben lost a mitten. The mitten is ____. (he, him, or his)","Put these together: The pond is frozen. The pond is smooth.","Make it a question: The cocoa is hot."],key:["skated","will","slide","his","The pond is frozen and smooth. (or uses but, or, so)","Is the cocoa hot?"]}]},{id:6,title:"Hot Cocoa Chat",short:"Cocoa Chat",parts:[{std:["SL.1.4"],n:3,label:"checks met",dur:60,html:()=>`<p class="big">Tell me about a time you played outside with someone.</p><ul class="qlist" style="margin-top:14px"><li>Who was with you?</li><li>What did you do?</li><li>How did you feel?</li></ul>`,key:["Names who was there and gives 1 or more details about them (SL.1.4)","Says what they did and where, with 2 or more details, all about this one time (SL.1.4)","Says how it made them feel, in at least 1 complete sentence (SL.1.4)"]}]},{id:7,title:"Animals in Winter",short:"Animals",parts:[{title:"Winter Sleep",std:["RI.1.1"],dur:75,html:()=>`<p class="passage">${GROUNDHOG}</p>`,qs:["What does a groundhog do in the fall?","Where does a groundhog sleep all winter?","Ask me one question about groundhogs."],key:["It eats a lot of food (RI.1.1)","In a den it digs under the ground (RI.1.1)","Asks a real question about groundhogs (RI.1.1)"]},{wt:"facts",gxHome:13,title:"Facts Writing",std:["W.1.2","W.1.8","L.1.1"],n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write about groundhogs. Tell 2 facts you learned from Winter Sleep.</p><ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul><details class="look-back" open><summary>Look back at Winter Sleep</summary><p class="passage" style="font-size:1.5rem">${GROUNDHOG}</p></details>`,key:["Names the topic (W.1.2)","Gives at least 2 facts (W.1.2)","Facts come from the Winter Sleep passage (W.1.8)","Gives some sense of closure (W.1.2)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]},{title:"Frozen Pond",std:["SL.1.2"],n:4,dur:75,read:POND,html:()=>`<p class="huge" aria-hidden="true">${ICON("skate",96)}</p>`,key:["What happens to the top of a pond when the air gets very cold? (it turns to ice) (SL.1.2)","Where do the fish go once there is ice on top? (they still swim in the water under the ice) (SL.1.2)","How does the village worker find out how thick the ice is? (drills a small hole and drops in a stick to measure it) (SL.1.2)","“Ask me one question about the frozen pond.” (asks 1 question that is about what was read and starts with a question word, such as: How cold does the air have to get?) (SL.1.2)"]}]},{id:8,title:"Snowflake Numbers",short:"Numbers",parts:[{title:"Hop and Count",std:["1.OA.C.5"],dur:30,qs:["Start at 9. Count on 4. Where do you land? What adding sentence is that?","Start at 15. Count back 3. What taking away sentence is that?"],key:["10, 11, 12, 13. 9 + 4 = 13 (1.OA.C.5)","14, 13, 12. 15 - 3 = 12 (1.OA.C.5)"]},{title:"Big Numbers",std:["1.NBT.A.1"],dur:75,qs:["Count out loud from 88 to 105.","Read these numbers out loud: 47, 101, 116.","Write the number one hundred thirteen.","Count the snowflakes. Write the number that tells how many."],fig2:()=>F.row(F.objects("snowflake",17,6)),key:["88, 89 ... 99, 100, 101 ... 105. Watch the jump past 99 (1.NBT.A.1)","Forty-seven, one hundred one, one hundred sixteen (1.NBT.A.1)","113, not 10013 (1.NBT.A.1)","17 (1.NBT.A.1)"]},{title:"Stacks of Ten",std:["1.NBT.B.2"],dur:30,fig:()=>F.row(F.tens(5,3)),qs:["What number is this? How many tens and ones?","What does the 7 in 72 mean?"],key:["53. 5 tens and 3 ones (1.NBT.B.2)","7 tens, or 70 (1.NBT.B.2)"]}]},{id:9,title:"Snowball Problems",short:"Snowballs",parts:[{title:"Story Problems",std:["1.OA.A.1"],dur:60,qs:["Ruby rolled 14 snowballs. Some of them broke apart. Now she has 6 left. How many broke apart? Write a number sentence with a box for the number you don’t know.","Leo cleared 7 steps. Maya cleared 13 steps. How many more steps did Maya clear?"],key:["14 - □ = 6 or 14 - 6 = □; answer 8 (1.OA.A.1)","6 (1.OA.A.1)"]},{title:"Smart Adding",std:["1.OA.B.3"],dur:30,qs:["9 + 5 = 14. So what is 5 + 9?","Add 3 + 8 + 7. Which two numbers would you add first? Why?"],key:["14, knows without counting (1.OA.B.3)","18. Adds 3 + 7 to make 10, then 10 + 8 (1.OA.B.3)"]}]},{id:10,title:"Shovel the Walk",short:"Shoveling",parts:[{title:"Add It Up",std:["1.NBT.C.4"],dur:60,qs:["52 + 6","31 + 40","46 + 7. Show how you did it."],key:["58 (1.NBT.C.4)","71, adds tens to tens (1.NBT.C.4)","53, makes a new ten (drawing, tens and ones, or 46 + 4 + 3) and explains (1.NBT.C.4)"]},{title:"Tens Away",std:["1.NBT.C.6"],dur:30,qs:["80 - 30","70 - 40. Show how you know."],key:["50 (1.NBT.C.6)","30, uses tens (7 tens take away 4 tens) and explains (1.NBT.C.6)"]}]},{id:11,title:"Winter Fun Graph",short:"Fun Graph",parts:[{std:["1.MD.C.4"],kind:"graph",n:3,dur:60,html:()=>`<p class="big" style="margin-top:0">3 kids picked snowshoes. Finish the graph.</p>`,render:()=>F.row(graphHtml()),bind:(root,ctx)=>root.querySelectorAll(".oc").forEach(r=>r.onclick=()=>{const v=+r.dataset.r;E.state.shoe=(E.state.shoe||0)===v?v-1:v;E.save();ctx.redraw()}),qs:["How many kids are on the graph in all?","How many more kids picked the sled than the skates?"],key:["Snowshoes bar filled to 3. Click the squares as the student tells you.","8 + 5 + 3 = 16 kids in all","Sled (8) minus skates (5) = 3 more"]}]},{id:12,title:"Cabin Workshop",short:"Cabin",parts:[{title:"Measure It",std:["1.MD.A.2"],dur:30,fig:()=>measureFig(),qs:["How many cubes long is the sled?","Is the ski measured the right way? Why or why not?"],key:["6 cubes (1.MD.A.2)","No. The cubes are not all the same size, so counting them does not tell how long the ski is. Units must be the same size (1.MD.A.2)"]},{title:"Cabin Clocks",std:["1.MD.B.3"],dur:40,fig:()=>F.row([F.clock(7,0),"Clock A"],[F.clock(11,30),"Clock B"],[F.digital("4:00"),"Clock C"]),qs:["Write the time on Clock A.","Write the time on Clock B.","Read Clock C out loud. On a clock with hands, where would the long hand point at that time?"],key:["7:00 (1.MD.B.3)","11:30 (1.MD.B.3)","4:00. The long hand points straight up at the 12 (1.MD.B.3)"]},{title:"Cut It Fair",std:["1.G.A.3"],dur:70,fig:()=>sharesFig(),qs:["What do we call the shaded part of the circle?","Which rectangle shows fourths? How do you know?","Rectangle A is cut into fourths. How many of those parts make the whole rectangle? Is one of those parts bigger or smaller than one half of that rectangle?","Draw a circle on your paper. Cut it into 4 equal parts. Hold it up."],key:["A fourth, a quarter, or one of four equal parts (1.G.A.3)","Rectangle A. Its four parts are the same size (1.G.A.3)","Four of the parts, or four fourths, make the whole rectangle. One fourth is smaller than one half, because cutting the whole into more equal parts makes each part smaller (1.G.A.3)","Draws a circle cut into 4 parts that are about the same size (1.G.A.3)"]}]},{id:13,title:"Write by the Fire",short:"Write",parts:[{wt:"story",title:"Story Writing",std:["W.1.3","L.1.1"],n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write about a cold day outside, or a day you helped someone. Tell what happened first, next, and last.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>`,key:["Tells 2 or more events in order (W.1.3)","Includes some details about what happened (W.1.3)","Uses time words like first, next, then (W.1.3)","Gives some sense of closure (W.1.3)","Prints upper and lowercase letters correctly (L.1.1)","Writes complete sentences (L.1.1)"]}]},{id:14,title:"Copy a Fox Paw",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A fox crosses packed snow. It does it all winter without slipping. Each paw has a bottom. It is covered in thick fur. Stiff hairs stick out. They are between the toe pads.</p>
     <div class="figure">${ICON("fox",104)}${ICON("paws",88)}</div>
     <p class="big">People in the village keep sliding. The path to the well is icy.</p>`,qs:["How do thick fur and stiff hairs on the bottom of a paw help a fox walk on slippery snow?","Draw a boot sole for the villagers that copies the bottom of the fox's paw.","Tell me which animal part you copied and how your sole keeps a foot from sliding."],key:["The rough hairs catch and grip instead of sliding across the surface, the way a smooth sole does. Any answer about gripping or roughness counts.","Any sole drawn with grip: bumps, ridges, spikes, a rough or hairy surface, deep grooves. A smooth sole is partial, so ask what the bottom of the fox's paw is like.","Needs both halves: names the furry gripping paw bottom as the part copied, and says the rough surface grabs the ice instead of sliding over it."]}]},{id:15,title:"Deer and Fawn",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"At the edge of the village a deer and her fawn come out of the pines each afternoon. She walks ahead and the fawn follows, stepping in the tracks she has already made in the deep snow. When she reaches a place where the wind has blown the snow thin, she stops and paws at the ground until the grass underneath shows. The fawn comes up beside her and eats there. When she lifts her head and takes one step back toward the pines, the fawn turns and follows her again.",qs:["What does the fawn do every time the deer walks ahead through deep snow?","What does the fawn do when the deer paws the snow away from the grass?","How does stepping in the parent's tracks help a young fawn get through deep snow?"],key:["It follows, stepping in the tracks she has already made. Every time is what makes it a pattern.","It comes up beside her and eats the grass she uncovered.","The snow in her tracks is already pushed down, so the fawn does not have to break a path and uses much less of its strength."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A young pine and the grown pine beside it. A fawn and the deer that is its parent.</p>
     <div class="figure">${ICON("sprout",92)}${ICON("pine",104)}</div>
     <div class="figure">${ICON("deer",92)}${ICON("deer",112)}</div>`,qs:["Name one way the young pine is like the grown pine.","Name one way the young pine is not exactly like the grown pine.","A fawn has white spots on its back and the grown deer does not. Does having spots mean the fawn is not that deer's young? Say why."],key:["Both have green needles, both have a straight trunk, both stay green in winter. Any likeness counts.","The young one is much shorter, thinner, and has far fewer branches. Any difference counts.","No. Young animals are like their parents but not exactly like them, and the spots are one of those differences. The spots fade as the fawn grows."]}]},{id:16,title:"The Sunset Log",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">The village keeper writes down the time the sun goes down behind the ridge.</p>
     <table class="bigTable"><tr><th>Day</th><th>Time the sun went down</th></tr>
     <tr><td>Monday</td><td>4:38</td></tr><tr><td>Tuesday</td><td>4:39</td></tr>
     <tr><td>Wednesday</td><td>4:41</td></tr><tr><td>Thursday</td><td>4:42</td></tr></table>
     <div class="figure">${ICON("sun",84)}${ICON("mountain",84)}${ICON("moon",84)}</div>`,qs:["Is the sun going down a little earlier or a little later each day?","On Friday, do you predict the sun will go down before 4:42 or after it? Say how you know.","The sun has gone down behind the same ridge every single evening. Where do you predict it will go down next week?","The moon has looked a little fuller every night for five nights. What do you predict it will look like tomorrow night?"],key:["a little later each day. 4:38, 4:39, 4:41, 4:42","After 4:42. The times are growing by a minute or two each day, and a pattern that repeats lets you predict the next one.","Behind the same ridge. It has done it every evening, so it can be predicted.","Fuller again, or full. The shapes change in a pattern that keeps going the same way."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">Hours of daylight in the village, counted on one day in each of three months.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>December</td><td>9</td></tr><tr><td>March</td><td>12</td></tr>
     <tr><td>June</td><td>15</td></tr></table>`,qs:["Which of these three months has the fewest hours of daylight?","How many more hours of daylight does June have than December?","Children sled after school. In which of these months would they have the most light left to sled in, and how does the chart tell you?"],key:["December, 9 hours","6 more hours. 15 take away 9","June, because June has 15 hours of daylight and December only 9. More hours of daylight means more light left after school."]}]},{id:17,title:"Bells and Shaking",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a small bell, ring it first. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Ring a small bell and then close your hand round it while it is still ringing.</p>
     <div class="figure">${ICON("clock",96)}${ICON("pan",96)}</div>
     <p class="big">Now sprinkle a pinch of salt on a piece of plastic wrap stretched tight over a bowl. Bang a pot hard right beside it, without touching the bowl.</p>`,qs:["While the bell is ringing, what is the metal of the bell doing?","You close your hand round the bell. What happens to the sound, and why?","When the pot is banged beside the bowl, what does the salt do?","Nothing touched the salt. What does its jumping tell you that sound can do?"],key:["Shaking back and forth very fast. Buzzing, humming, vibrating, all count. A student who says the clapper is moving is partly right, so ask what the metal itself does.","The sound stops almost at once, because your hand holds the metal still and stops the shaking. No shaking, no sound.","It hops and jumps on the stretched wrap.","A sound can make a thing shake from across a gap. The banged pot made the wrap shake, and the shaking wrap threw the salt into the air."]}]},{id:18,title:"The Dark Cabin",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The cabin shutters are closed for the night and the lamp is not lit. No light gets in.</p>
     <div class="figure">${ICON("sled",96)}${ICON("lamp",96)}</div>`,qs:["The sled is standing just inside the cabin door. Can you see it with the shutters closed and the lamp out? Say why or why not.","What has to happen before anyone can see the sled?","A white mitten is on the floor in the same dark room. Does being white let you see it without any light? Say why."],key:["No. No light reaches the sled, and a thing can only be seen when light shines on it and bounces back to your eyes.","Light has to reach it: the lamp lit, a flashlight switched on, or a shutter opened to let light in.","No. White only looks bright because it bounces back a lot of light. With no light there is nothing for it to bounce, so it cannot be seen."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">In the dark cabin one flashlight beam was pointed at four things and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear block of ice</td><td>went through, a little wobbly</td></tr>
     <tr><td>a wool scarf</td><td>a dim glow came through</td></tr>
     <tr><td>a closed wooden shutter</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a shiny tin lid</td><td>bounced back toward the flashlight</td></tr></table>`,qs:["Which thing let the most light through?","Which thing let the least light through?","The wool scarf let a dim glow through. Could you read a word written on a card behind it? Say why.","Two of the four leave the room darker behind them, but only one of those sends the light back where it came from. Name each one and say which is which."],key:["the clear block of ice","the closed wooden shutter","No. A dim glow is not enough light to make out small shapes like letters. Some light gets through, but not a clear picture.","The shutter stops the light and makes a shadow. The shiny tin lid sends it back toward the flashlight. Both leave the space behind them darker, but only the lid bounces the beam."]}]},{id:19,title:"The Far Cabin",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">One cabin stands alone across the valley. Snow lies deep between the two and nobody can shout that far.</p>
     <div class="figure">${ICON("cabin",88)}${ICON("lamp",88)}${ICON("megaphone",88)}</div>`,qs:["Draw a device that tells the far cabin that the path has been shovelled clear. It has to use light or sound.","Name the device you drew and say which one it uses, light or sound.","Snow is falling thickly between the two cabins. Which carries better through falling snow, a light or a sound? Say what you would choose and why."],key:["Any device that carries light or sound across the valley: a lamp set in the window, a lamp flashed on and off, a bell, a horn, a whistle, a drum.","Names it and says which one it uses.","A sound, because falling snow blocks the view but sound still travels through it. A student who argues for a very bright light and explains their reasoning is thinking well, so take the reasoning rather than the answer."]}]},{id:20,title:"Fix the Slipping Rope",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"The village sled is pulled up the hill by a plain rope tied to the front. The children wear thick mittens. Halfway up the hill the rope slides out of a mittened hand, and whoever is pulling has to stop, turn round, and go back down for it.",qs:["What is the problem the children want to change?","What is one thing you would ask the children before you tried to fix it?","What is the first thing you would watch, before any building starts?"],key:["The rope slips out of a mittened hand partway up the hill.","Any real question: how thick is the rope, how slippery are the mittens, how heavy is the sled, how steep is the hill, where on the rope does the hand hold. A statement is not a question, so ask once more.","Any real observation: count how many times it slips in ten pulls, watch where the hand holds, feel how slippery the mitten is, see whether it slips more on the steep part."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw a better end for the sled rope, one a mittened hand will not lose.</p>
     <div class="figure">${ICON("sled",88)}${ICON("mitten",88)}${ICON("ruler",88)}</div>`,qs:["Draw your fix on the end of the rope.","Point to the part the hand holds and tell me its shape.","Tell me why that shape stays in a mitten better than the plain end of a rope."],key:["Any real fix: a loop to put a wrist through, a crossbar handle, a thick knot, a wooden grip, a strap round the hand.","Names a shape: a round loop, a straight bar across, a fat knot, a hooked grip.","Because the shape catches on the hand or the wrist instead of sliding through it. A plain rope end has nothing to catch on."]}]},{id:21,title:"Which Handle Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two rope handles were tested with the same thick mittens, ten pulls up the same hill each.</p>
     <table class="bigTable"><tr><th>Handle</th><th>Times it slipped, out of 10</th></tr>
     <tr><td>a wrist loop</td><td>1</td></tr>
     <tr><td>a fat knot</td><td>4</td></tr></table>`,qs:["Which handle worked better in the test?","Say how the numbers in the chart tell you that.","Neither handle slipped zero times. Does that mean both failed? Say what the chart really shows."],key:["the wrist loop","The wrist loop slipped only 1 time out of 10 and the fat knot slipped 4 times out of 10. The numbers have to be in the answer.","No. Both are better than a plain rope, and the chart shows which of the two is better. A test tells you which one to choose, not only which ones are perfect."]}]},{id:22,title:"The Village Meeting",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and naming the responsibility that comes with a shared decision",read:"Once a month everyone in the village meets in the hall. Anybody who wants to speak puts a stone in the bowl by the door and gets a turn. This month they talked about the path between the houses. The path belongs to no one person, so everyone may walk on it. They decided that each household would clear the snow from the stretch of path in front of its own door. Twelve hands went up for that plan and four went up against it.",qs:["Every person at the meeting may put a stone in the bowl and get a turn to speak. Is that a right or a responsibility?","Clearing the snow in front of your own door is a job you take on. Is that a right or a responsibility?","Four people voted against the plan. Do they still have to clear the snow in front of their door? Say why.","Name one rule in your own home or class and say who it helps."],key:["a right","a responsibility","Yes. The whole village decided together, and a decision everyone made counts for everyone, even those who wanted something else. They can ask to talk about it again at the next meeting.","Any real rule with who it helps named: taking turns helps everyone get a go, hanging up a coat keeps the floor clear for everybody, quiet voices help people who are working."]}]},{id:23,title:"The Village Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the village, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ICON("pine",56)}</td><td>${ICON("mountain",56)}</td><td></td></tr>
     <tr><th>B</th><td>${ICON("cabin",56)}</td><td></td><td>${ICON("cabin",56)}</td></tr>
     <tr><th>C</th><td></td><td>${ICON("bridge",56)}</td><td>${ICON("drop",56)}</td></tr></table>
     <p class="big">${ICON("pine",48)} the pine wood &nbsp; ${ICON("mountain",48)} the ridge &nbsp; ${ICON("cabin",48)} houses &nbsp; ${ICON("bridge",48)} the bridge &nbsp; ${ICON("drop",48)} the frozen pond</p>
     <p class="big">The winters here are long and cold, and deep snow lies on the ridge for months.</p>`,qs:["Find the bridge. Give its exact spot on the grid, the letter and the number.","Where is the pine wood compared to the bridge? Use words like above, below, left of, or right of.","Which two things on this map were not built by anybody?","The winters here are long and cold. Name one thing people in this village would wear, one way they would travel in the snow, and one thing they would do for fun that people in a hot dry place would not."],key:["C2. Both parts are needed.","Above the bridge and to the left of it. Up and over counts too.","The pine wood, the ridge, or the frozen pond.","Any true set of three. Wear: a thick coat, boots, a hat, gloves. Travel: a sled, snowshoes, skis, a snowplow on the road. For fun: skating on the pond, sledding, skiing, building in the snow. All three parts are what is being checked, because this standard is about the way a place and its weather change how people live. (HSS-1.2)"]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">Nine families live in this village. They came from six different places. In one house they sing. They sing in a language. None of the others speak it. At the village supper each brings food. Every family brings something different.</p>
     <div class="figure">${ICON("cabin",88)}${ICON("soup",88)}${ICON("books",88)}</div>`,qs:["Do the families in a small village all come from the same place? Say how the story shows the answer.","Name three things people built in the place where you live, and say what one of them is for.","Two children live on the same street but speak different languages at home. Name one thing they still share just by living on the same street."],key:["No. Nine families came from six different places, and one house sings in a language the others do not speak.","Any three built things, with a use for one of them: a school for learning, a store for food, a road for traveling, a park, a bus stop, a library.","Any real shared thing: the same street, the same school, the same park, the same shops, the same bus, the same weather, the same neighbors."]}]},{id:24,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what the parts of the national flag stand for and naming a tradition people share",html:()=>`<p class="big">The United States flag has thirteen stripes. Seven are red. Six are white. There were thirteen states then. That was when the country began. There is one stripe each. There is one for each of them.</p>
     <div class="figure">${ICON("flag",110)}${ICON("star",96)}</div>`,qs:["How many stripes are on the flag of the United States, and what does each one stand for?","The country has far more than thirteen states now, but the number of stripes has never changed. What do you think the stripes are there to remind people of?","In classrooms all over the country children stand, face the flag, and put a hand over the heart while they say the Pledge of Allegiance. Why do people do the same thing in the same way in so many different places?"],key:["Thirteen stripes, one for each of the thirteen states the country started with.","The beginning of the country, the states it started with. Any answer about remembering how it began counts.","Because it is a tradition that is shared, and doing it the same way shows that all those different classrooms belong to one country."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Keeping food cold through the winter and into the summer.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>where the cold came from</td><td>blocks of ice cut from the pond</td><td>a machine in the kitchen</td></tr>
     <tr><td>where food was kept</td><td>an ice house packed with sawdust</td><td>a refrigerator</td></tr>
     <tr><td>why people did it</td><td>so food would keep</td><td>so food would keep</td></tr></table>
     <div class="figure">${ICON("snowflake",88)}${ICON("milk",88)}</div>`,qs:["Long ago, where did people get the cold that kept their food?","Where does the cold come from today?","Tell me one way life is different now from the way it was long ago.","Point to the row where long ago and today say the same thing. Tell me what that row is about."],key:["Blocks of ice cut out of the frozen pond and packed away in an ice house.","A machine in the kitchen, a refrigerator.","Where the cold came from changed, or where food was kept changed. Either counts.","The reason: people still do it so that food will keep. That is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,html:()=>`<div style="text-align:center">${["footprint","repack","slowly"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["footprint (two syllables, compound word, oo vowel team)","repack (prefix re-)","slowly (suffix -ly)"]},4:{id:"L4",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,html:()=>`<p class="passage" style="font-size:1.5rem">${STORY}</p><ol class="qlist"><li>Why could Nico not get his sled out by himself?</li><li>How do you know Nico liked the ride down the hill?</li></ol>`,key:["It was stuck under a pine tree and he could not pull it out alone. It came free only when Tess pulled the other end. Accept either part","He called it the best ride of the whole winter"]},9:{id:"L9",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,html:()=>`<p class="big">The village cleared 24 paths on Monday. On Tuesday they cleared 18 more. Then new snow covered 7 of the paths. How many paths are still clear?</p>`,key:["35 (24 + 18 = 42, then 42 - 7 = 35)"]},10:{id:"L10",lv:true,title:"Level Up: Bigger Adding",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:2,html:()=>`<ol class="qlist"><li>38 + 27</li><li>73 - 46</li></ol>`,key:["65","27"]},12:{id:"L12",lv:true,title:"Level Up: Time Challenge",std:["2.MD.C.7"],needs:["1.MD.B.3"],n:2,html:()=>`${F.row(F.clock(6,15))}<ol class="qlist"><li>What time is it?</li><li>You wake up and eat breakfast at this time. Is it a.m. or p.m.?</li></ol>`,key:["6:15","a.m."]}};const DIRS={"1.0":"Listen to your teacher. Say the sounds and words out loud.","2.0":"Read each word out loud. The last two are silly words. Just sound them out.","3.0":"Look at the three pictures. Then read the story out loud in your best reading voice.","4.0":"Look at the story. Answer out loud.","4.1":"Listen while your teacher reads the story again if you need it. Answer out loud.","5.0":"Listen to your teacher read each one. Say your answer out loud.","6.0":"Talk for about one minute. Speak clearly.","7.0":"Read about the groundhog out loud. Then answer out loud.","7.2":"Listen carefully. Your teacher will read about a frozen pond. Then answer out loud.","8.0":"Answer out loud.","8.1":"Count and read out loud. Write your numbers on your paper and hold it up.","8.2":"Look at the blocks. Answer out loud.","9.0":"Listen to each problem. You can draw on your paper. Hold it up when you finish.","9.1":"Answer out loud. Tell how you know.","10.0":"Solve each one. Say 1 and 2 out loud. Show your work for 3 on your paper and hold it up.","10.1":"Solve each one. Tell how you know.","11.0":"Tell your teacher how many squares to color for snowshoes. Then answer out loud.","12.0":"Look at the pictures. Answer out loud.","12.1":"Write the times for A and B on your paper and hold it up.","12.2":"Look at the shapes. Answer out loud. Draw the last one on your paper.","4.2":"Write on your paper. When you finish, hold it up and read it to your teacher.","7.1":"Write on your paper. When you finish, hold it up and read it to your teacher.","13.0":"Write on your paper. When you finish, hold it up and read it to your teacher.","L2":"Read each word out loud.","L4":"Answer out loud. Use the story.","L9":"Solve on your paper. Tell your teacher the answer.","L10":"Solve on your paper and hold it up.","L12":"Look at the clock. Answer out loud."};STOPS.forEach(st=>st.parts.forEach((p,i)=>{const d=DIRS[st.id+"."+i];if(d)p.dir=d;else if(!p.dir)p.dir=""}));Object.values(LEVELUPS).forEach(l=>{l.dir=DIRS[l.id]||""});const DESC={"1.0":"blending and segmenting sounds in spoken words","2.0":"reading words with digraphs, final e, vowel teams, endings, and two syllables","3.0":"a 75-word grade-level story read aloud","4.0":"the first word, capital letters, and end marks in sentences","4.1":"key detail questions about a story","5.0":"spoken grammar items (verb tense, pronouns, joining sentences, questions)","6.0":"describing a person and an event with details","7.0":"key detail questions about an informational text","7.2":"asking and answering questions about a text read aloud","8.0":"counting on and back to add and subtract","8.1":"counting, reading, and writing numbers to 120","8.2":"tens and ones in two-digit numbers","9.0":"addition and subtraction word problems within 20","9.1":"using properties of addition as strategies","10.0":"adding within 100","10.1":"subtracting multiples of 10","11.0":"finishing and reading a bar graph with three categories","12.0":"measuring length with same-size units","12.1":"telling time to the hour and half hour","12.2":"halves and fourths of circles and rectangles","4.2":"an opinion writing piece","7.1":"an informative writing piece","13.0":"a narrative writing piece"};STOPS.forEach(st=>st.parts.forEach((p,i)=>{const d=DESC[st.id+"."+i];if(d)p.desc=d;else if(!p.desc)p.desc=""}));const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},blk=[0,0],c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function blkHtml(){return`<div class="blk-row"><button class="chip" data-b="0" data-d="1">Add a ten</button><button class="chip" data-b="0" data-d="-1">Take a ten</button><button class="chip" data-b="1" data-d="1">Add a one</button><button class="chip" data-b="1" data-d="-1">Take a one</button><button class="chip" data-b="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]?F.tens(blk[0],blk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} tens and ${blk[1]} ones on the mat.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["In the story, ____.","I think Tess was ____.","One reason is ____.","So ____."],facts:["My topic is ____.","One fact is ____.","Another fact is ____.","That is how ____."],story:["One cold day, ____.","First, ____.","Then, ____.","Last, ____.","It made me feel ____."]};function sentHtml(st){const wt=st.parts&&st.parts[0].wt||"opinion";return`<ul class="starters">${STARTERS[wt].map(x=>`<li>${x}</li>`).join("")}</ul>`}function tpsClockHtml(){return F.row([F.clock(3,0,170),"3:00, three o'clock"],[F.clock(7,30,170),"7:30, half past seven"])+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{if(x.dataset.b==="x")blk=[0,0];else{const i=+x.dataset.b;blk[i]=Math.max(0,Math.min(i?19:9,blk[i]+ +x.dataset.d))}r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting and reading with it open is supported, not independent."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.2","W.1.3"],msg:"If an adult wrote for the student, do not rate the printing check for L.1.1."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
